import {createBathLoading} from './bath-loading-v72.js';
import {albumPhotos} from './return-loading-v84.js';
// All city portals and map clicks share this same tested landing policy.
export function cityMapWorld(p){const cx=BigInt(p.cx),cz=BigInt(p.cz),limit=140737488355327n;if(cx>limit||cx< -limit||cz>limit||cz< -limit||!Number.isFinite(p.x)||!Number.isFinite(p.z))throw Error('Destination outside precise city coordinates');return{x:Number(cx)*64+p.x,z:Number(cz)*64+p.z,yaw:p.yaw};}
export function cityLandingClear(x,z,solids,pad=.32){return !solids.some(q=>{if(q.kind==='circle')return Math.hypot(x-q.x,z-q.z)<q.r+pad;const c=Math.cos(q.ry||0),s=Math.sin(q.ry||0),dx=x-q.x,dz=z-q.z;return Math.abs(c*dx-s*dz)<q.w/2+pad&&Math.abs(s*dx+c*dz)<q.d/2+pad;});}
export function findCityLanding(target,solids){if(!Number.isFinite(target.x)||!Number.isFinite(target.z))return null;const nearby=solids.filter(q=>Math.hypot(q.x-target.x,q.z-target.z)<48+(q.r||Math.hypot(q.w,q.d)/2));const clear=(x,z)=>cityLandingClear(x,z,nearby);if(clear(target.x,target.z))return{x:target.x,z:target.z};for(let radius=.65;radius<=40;radius+=.65){const samples=Math.max(16,Math.ceil(radius*8));for(let i=0;i<samples;i++){const a=i/samples*Math.PI*2,x=target.x+Math.sin(a)*radius,z=target.z+Math.cos(a)*radius;if(clear(x,z))return{x,z};}}return null;}
export function cityLocalPose(p){const cx=BigInt(Math.floor(p.x/64)),cz=BigInt(Math.floor(p.z/64));return{cx,cz,x:p.x-Number(cx)*64,z:p.z-Number(cz)*64};}
export function createCityTransit(){const album=createBathLoading(document.body,{slides:albumPhotos('city'),title:'LEVEL 11 / TRANSIT',opening:'正在准备城市街区',alt:'无人美国城市与商业街的旧数码照片',returnText:'返回原处'});album.element.classList.add('city-transit');return{show:()=>album.show(),progress:album.progress,hide:()=>album.finish(),dispose:()=>album.dispose()};}
